        {
            if (string.IsNullOrEmpty(label))
                return null;
            if (!ignoreCooldown)
            {
                if (Time.unscaledTime < _cooldown)
                    return null;
                _cooldown = Time.unscaledTime + 0.15f;
            }

            string key = label.Trim().ToLowerInvariant();
